const printVendorBillElement=async()=>{const source=document.querySelector<HTMLElement>(".vendor-bill");if(!source)return;const clone=source.cloneNode(true) as HTMLElement;clone.classList.add("print-clone");const images=[...clone.querySelectorAll("img")];images.forEach(image=>{const src=image.getAttribute("src");if(src)image.src=new URL(src,window.location.href).href});document.body.appendChild(clone);document.body.classList.add("print-vendor-bill");const cleanup=()=>{clone.remove();document.body.classList.remove("print-vendor-bill");window.removeEventListener("afterprint",cleanup)};window.addEventListener("afterprint",cleanup);await Promise.all(images.map(image=>image.decode().catch(()=>undefined)));if(document.fonts)await document.fonts.ready;await new Promise<void>(resolve=>requestAnimationFrame(()=>requestAnimationFrame(()=>resolve())));window.print();setTimeout(()=>{if(document.body.contains(clone))cleanup()},60000)};
