 const [billCreatorOpen,setBillCreatorOpen]=useState(false),[billItems,setBillItems]=useState<BillItem[]>([billItem()]),[charges,setCharges]=useState<BillCharges>(billCharges),[billDate,setBillDate]=useState(today()),[createdBill,setCreatedBill]=useState<CreatedBill|null>(null),[paymentReceipt,setPaymentReceipt]=useState<VendorPayment|null>(null);
