  capture.classList.remove("print-clone");capture.style.position="fixed";capture.style.left="-10000px";capture.style.top="0";capture.style.display="block";capture.style.width="900px";capture.style.maxWidth="none";capture.style.height="1350px";capture.style.borderRadius="0";capture.style.boxShadow="none";
